package vn.boardinghub.modules.room;import jakarta.persistence.*;import vn.boardinghub.modules.property.Property;import vn.boardinghub.shared.persistence.BaseEntity;import java.math.BigDecimal;
@Entity @Table(name="rooms",uniqueConstraints=@UniqueConstraint(name="uk_room_property_code",columnNames={"property_id","code"}))public class Room extends BaseEntity{@ManyToOne(optional=false)@JoinColumn(name="property_id")private Property property;@Column(nullable=false,length=30)private String code;@Column(nullable=false,precision=12,scale=2)private BigDecimal monthlyRent;@Column(nullable=false)private int capacity;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private RoomStatus status=RoomStatus.VACANT;@Column(length=500)private String description;protected Room(){}public Room(Property p,String c,BigDecimal rent,int cap,String d){property=p;code=c;monthlyRent=rent;capacity=cap;description=d;}public Property getProperty(){return property;}public String getCode(){return code;}public BigDecimal getMonthlyRent(){return monthlyRent;}public int getCapacity(){return capacity;}public RoomStatus getStatus(){return status;}public String getDescription(){return description;}public void update(String c,BigDecimal rent,int cap,String d){code=c;monthlyRent=rent;capacity=cap;description=d;}}
